  Write-Output "ERR: $($_.Exception.Message)"
  if ($_.Exception.Response) {
    $sr = New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream())
    Write-Output $sr.ReadToEnd()
  }
}

$base = "http://zentao-biz.zhi.com"
$tok = "ccabde64fcf15475803644321e4b2d25"
$outDir = "D:\repository\门户\.tmp_task1497"
New-Item -ItemType Directory -Force -Path $outDir | Out-Null
$hd = @{ 'Token' = $tok; 'Accept' = 'application/json' }
foreach ($id in 15177,15180,15181,15182,15183) {
  try {
    $r = Invoke-WebRequest -Uri "$base/api.php/v1/files/$id" -Headers $hd -UseBasicParsing
