83: const PUBLISHED = '1'
84: // String.fromCharCode 展开参数过多会栈溢出，正文含内嵌图片时需分段转换
85: const BASE64_CHUNK_SIZE = 0x8000
86: 
87: /** UTF-8 正文 Base64 编码：规避网关 XSS 过滤破坏富文本，后端解码后按白名单清洗 */
88: function encodeContent(html) {
89:   const bytes = new TextEncoder().encode(html || '')
90:   let binary = ''
91:   for (let i = 0; i < bytes.length; i += BASE64_CHUNK_SIZE) {
92:     binary += String.fromCharCode.apply(null, bytes.subarray(i, i + BASE64_CHUNK_SIZE))
93:   }
94:   return btoa(binary)
95: }
