3: # 接口代理：http://192.168.1.199:8081（与 vite dev proxy 路径一致）
4: #
5: # 使用方式（Linux 示例）：
6: #   1. 构建：本地部署请用 npm run build:local（放开账号密码登录）；常规环境用 npm run build
7: #   2. 修改下方 root 为 dist 实际绝对路径
8: #   3. sudo cp deploy/nginx.conf /etc/nginx/conf.d/portal.conf
9: #   4. sudo nginx -t && sudo nginx -s reload
10: 
11: upstream portal_backend {
12:     server 192.168.1.199:8081;
13:     keepalive 32;
14: }
15: 
16: server {
17:     listen 8099;
18:     server_name localhost;
19: 
20:     root D:/repository/门户/dist;
21:     index index.html;
22: 
23:     charset utf-8;
24:     client_max_body_size 100m;
25: 
26:     # 代理公共配置（以下所有 proxy_pass 的 location 自动继承，无需逐个重复）
27:     proxy_http_version 1.1;
28:     proxy_set_header Connection "";
29:     proxy_set_header Host $host;
30:     proxy_set_header X-Real-IP $remote_addr;
31:     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
32:     proxy_set_header X-Forwarded-Proto $scheme;
33:     proxy_set_header X-Proxy-Target-Url "http://192.168.1.199:8081$request_uri";
34:     # 响应头：返回给浏览器；always 确保 502/504 等错误时也能看到（proxy_set_header 仅发给后端，失败时到不了）
35:     add_header X-Proxy-Target-Url "http://192.168.1.199:8081$request_uri" always;
36:     proxy_connect_timeout 60s;
37:     proxy_send_timeout 120s;
38:     proxy_read_timeout 120s;
39: 
40:     # 静态资源缓存
41:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|json|pdf)$ {
42:         expires 7d;
43:         add_header Cache-Control "public" always;
44:         add_header X-Proxy-Target-Url "http://192.168.1.199:8081$request_uri" always;
45:         try_files $uri =404;
46:     }
47: 
48:     # 业务 API（与 env/.env 中 VITE_APP_BASE_API、VITE_APP_PORTAL_BASE_API 一致）
49:     location /api/v2.0/ {
50:         proxy_pass http://portal_backend;
51:     }
52: 
53:     location /api/v3.0/ {
54:         proxy_pass http://portal_backend;
55:     }
56: 
57:     # 兼容旧前缀
58:     location /v3.0/ {
59:         proxy_pass http://portal_backend;
60:     }
61: 
62:     # 兼容历史/多环境网关前缀（与 vite.config.js server.proxy 一致）
63:     location /zhi2/ {
64:         proxy_pass http://portal_backend;
65:     }
66: 
67:     location /zhi2-dev/ {
68:         proxy_pass http://portal_backend;
69:     }
70: 
71:     location /zhi2-test/ {
72:         proxy_pass http://portal_backend;
73:     }
74: 
75:     # 前端路由（Vue Router 默认 hash 模式；history 模式需 try_files 回退）
76:     location / {
77:         try_files $uri $uri/ /index.html;
78:     }
79: 
80:     # 禁止访问隐藏文件
81:     location ~ /\. {
82:         deny all;
83:     }
84: }

