1: # 门户(zhi2-web-admin) 本地部署 —— nginx 站点 (root 指向本项目 dist)
2: # 代理对齐 env VITE_APP_PROXY_ADDRESS（v2 网关）
3: 
4: # ---- 弱网优化：文本资源压缩 ----
5: # dist 里 js+css 共 21.2MB，gzip 后 6.8MB（约 32%）。
6: # 原来没有开 gzip，弱网/移动网络下首屏同步资源 1.17MB 原样传输，是白屏等待的主因之一。
7: # 这里只压缩文本类资源（图片/字体已是二进制，压缩反而浪费 CPU）。
8: # text/html 在没有显式 gzip_types 时总是被压缩，这里显式列出便于阅读。
9: gzip on;
10: gzip_comp_level 5;
11: gzip_min_length 1024;
12: gzip_vary on;
13: gzip_proxied any;
14: gzip_http_version 1.1;
15: gzip_types
16:     text/plain
17:     text/css
18:     text/xml
19:     text/javascript
20:     application/javascript
21:     application/json
22:     application/manifest+json
23:     application/xml
24:     application/rss+xml
25:     application/atom+xml
26:     image/svg+xml
27:     font/ttf
28:     font/otf;
29: 
30: server {
31:     listen 8092;
32:     server_name localhost;
33:     root D:/repository/门户/dist;
34:     index index.html;
35:     charset utf-8;
36:     client_max_body_size 100m;
37: 
38:     # 代理公共配置（以下 all proxy_pass location 继承）
39:     proxy_http_version 1.1;
40:     proxy_set_header Connection "";
41:     proxy_set_header Host unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
42:     proxy_set_header X-Real-IP $remote_addr;
43:     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
44:     proxy_set_header X-Forwarded-Proto $scheme;
45:     proxy_connect_timeout 60s;
46:     proxy_send_timeout 120s;
47:     proxy_read_timeout 120s;
48: 
49:     # 静态资源缓存
50:     # 文件名带内容 hash，可以长缓存；配合下方的 /index.html no-cache，
51:     # 发版后用户刷新即拿到新 HTML，chunk 命中本地缓存不重复下载。
52:     location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot|map|xlsx|json)$ {
53:         # 注意：add_header 会让本 location 不再继承上层 Cache-Control，
54:         # 所以这里只写一条完整的 Cache-Control（别再配 expires，避免出现两个 max-age）。
55:         add_header Cache-Control "public, max-age=2592000, immutable" always;
56:         access_log off;
57:         try_files $uri =404;
58:     }
59:     location = /index.html {
60:         expires -1;
61:         add_header Cache-Control "no-cache, no-store, must-revalidate";
62:         add_header Pragma "no-cache";
63:     }
64:     # 站点版本号（前端发版检测用）：不缓存，弱网下也要拿到最新值
65:     location = /version.json {
66:         add_header Cache-Control "no-cache, no-store, must-revalidate";
67:     }
68: 
69:     # 业务 API（门户网关：保留 /api/v2.0、/api/v3.0 前缀）
70:     location /api/v2.0/ {
71:         proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
72:     }
73:     location /api/v3.0/ {
74:         proxy_pass http://unlimited.g.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com;
75:     }
76:     # 附件/静态代理（对齐 vite /zhi2* proxy）
