1: <template>
2:   <div class="attachment-panel">
3:     <template v-if="!disabled">
4:       <input ref="fileInput" type="file" :accept="acceptAttr" style="display: none" @change="handleFileChange" />
5:       <zs-button type="primary" :loading="uploading" @click="triggerSelect">选取文件</zs-button>
6:       <div class="upload-tip">请上传大小不超过{{ fileSize }}mb,格式为Word、Excel、图片、PDF格式的文件</div>
7:     </template>
8:     <div v-for="(file, index) in value" :key="file.fileSite + index" class="attachment-item">
9:       <i class="el-icon-document attachment-icon" />
10:       <span class="attachment-name" :title="file.fileName">{{ file.fileName }}</span>
11:       <span class="attachment-actions">
12:         <a v-if="!disabled" class="action-delete" @click="handleRemove(index)">删除</a>
13:         <a v-if="canPreview(file)" class="action-link" @click="handlePreview(file)">预览</a>
14:         <a class="action-link" @click="handleDownload(file)">下载</a>
15:       </span>
16:     </div>
17:     <div v-if="disabled && !value.length" class="attachment-empty">暂未上传附件</div>
18:   </div>
19: </template>
20: 
21: <script>
22: import { resolveServerAssetUrl } from '@/utils/resolveServerAssetUrl.js'
23: 
24: const UPLOAD_API = '/file/file/upload'
25: const IMAGE_EXTENSIONS = ['jpg', 'jpeg', 'png', 'gif', 'bmp']
26: // 与后端附件白名单保持一致
27: const ALLOWED_EXTENSIONS = ['doc', 'docx', 'xls', 'xlsx', ...IMAGE_EXTENSIONS, 'pdf']
28: 
29: function getExtension(fileName) {
30:   const dotIndex = (fileName || '').lastIndexOf('.')
31:   return dotIndex > -1 ? fileName.slice(dotIndex + 1).toLowerCase() : ''
32: }
33: 
34: export default {
35:   name: 'ExternalInfoAttachmentPanel',
36:   model: {
37:     prop: 'value',
38:     event: 'input'
39:   },
40:   props: {
41:     value: {
42:       type: Array,
43:       default: () => []
44:     },
45:     disabled: {
46:       type: Boolean,
47:       default: false
48:     },
49:     // 单个文件大小上限（MB）
50:     fileSize: {
51:       type: Number,
52:       default: 20
53:     },
54:     limit: {
55:       type: Number,
56:       default: 20
57:     }
58:   },
59:   data() {
60:     return {
61:       uploading: false
62:     }
63:   },
64:   computed: {
65:     acceptAttr() {
66:       return ALLOWED_EXTENSIONS.map((ext) => `.${ext}`).join(',')
67:     }
68:   },
69:   methods: {
70:     triggerSelect() {
71:       if (this.value.length >= this.limit) {
72:         this.$message.error(`附件最多上传${this.limit}个`)
73:         return
74:       }
75:       this.$refs.fileInput.click()
76:     },
77:     handleFileChange(event) {
78:       const file = event.target.files[0]
79:       // 重置以便重复选择同一文件
80:       event.target.value = ''
81:       if (!file || !this.validateFile(file)) {
82:         return
83:       }
84:       this.upload(file)
85:     },
86:     validateFile(file) {
87:       if (!ALLOWED_EXTENSIONS.includes(getExtension(file.name))) {
88:         this.$message.error('文件格式不正确，请上传Word、Excel、图片、PDF格式的文件')
89:         return false
90:       }
91:       if (file.size / 1024 / 1024 > this.fileSize) {
92:         this.$message.error(`上传文件大小不能超过${this.fileSize}MB`)
93:         return false
94:       }
95:       return true
96:     },
97:     // 文件服务对中文文件名处理不稳定，上传时改用安全文件名，展示仍保留原始文件名
98:     upload(file) {
99:       const ext = getExtension(file.name)
100:       const safeName = `upload_${Date.now()}_${Math.random().toString(16).slice(2)}.${ext}`
101:       const formData = new FormData()
102:       formData.append('file', new File([file], safeName, { type: file.type }), safeName)
103:       this.uploading = true
104:       this.$post(UPLOAD_API, formData, { headers: { 'Content-Type': 'multipart/form-data' } })
105:         .then((res) => {
106:           const fileSite = res && res.data && res.data.fileSite
107:           if (!fileSite) {
108:             this.$message.error('上传失败，请重试')
109:             return
110:           }
111:           this.$emit('input', [...this.value, { fileName: file.name, fileSite }])
112:           this.$message.success('上传成功')
113:         })
114:         .catch((error) => {
115:           console.error('对外信息附件上传失败', { fileName: file.name }, error)
116:         })
117:         .finally(() => {
118:           this.uploading = false
119:         })
120:     },
121:     handleRemove(index) {
122:       const list = [...this.value]
123:       list.splice(index, 1)
124:       this.$emit('input', list)
125:     },
126:     canPreview(file) {
127:       const ext = getExtension(file.fileName)
128:       return IMAGE_EXTENSIONS.includes(ext) || ext === 'pdf'
129:     },
130:     handlePreview(file) {
131:       const url = resolveServerAssetUrl(file.fileSite)
132:       if (IMAGE_EXTENSIONS.includes(getExtension(file.fileName))) {
133:         this.$store.dispatch('preview/openPreview', { urlList: [url], currentIndex: 0 })
134:       } else {
135:         window.open(url, '_blank', 'noopener')
136:       }
137:     },
138:     handleDownload(file) {
139:       const link = document.createElement('a')
140:       link.href = resolveServerAssetUrl(file.fileSite)
141:       link.download = file.fileName
142:       link.target = '_blank'
143:       link.rel = 'noopener'
144:       document.body.appendChild(link)
145:       link.click()
146:       document.body.removeChild(link)
147:     }
148:   }
149: }
150: </script>
151: 
