153: .attachment-panel {
154:   padding: 8px 4px;
155: }
156: 
157: .upload-tip {
158:   margin: 12px 0;
159:   font-size: 13px;
160:   color: #333333;
161: }
162: 
163: .attachment-item {
164:   display: flex;
165:   align-items: center;
166:   margin-bottom: 8px;
167:   padding: 12px 16px;
168:   background: #f7f8fa;
169:   border-radius: 4px;
170: }
171: 
172: .attachment-icon {
173:   margin-right: 8px;
174:   font-size: 18px;
175:   color: #c0c4cc;
176: }
177: 
178: .attachment-name {
179:   flex: 1;
180:   min-width: 0;
181:   overflow: hidden;
182:   white-space: nowrap;
183:   text-overflow: ellipsis;
184:   color: #606266;
185: }
186: 
187: .attachment-actions {
188:   flex-shrink: 0;
189:   margin-left: 12px;
190: }
191: 
192: .attachment-actions a {
193:   margin-left: 16px;
194:   cursor: pointer;
195: }
196: 
197: .action-delete {
198:   color: #f56c6c;
199: }
200: 
201: .action-link {
202:   color: var(--primary-color, #1677ff);
203: }
204: 
205: .attachment-empty {
206:   padding: 24px 0;
207:   text-align: center;
208:   color: #cccccc;
209: }
210: </style>

