import { expect } from '@playwright/test'
import { loadE2eEnv } from './env-loader.js'

loadE2eEnv()

export const PORTAL_ADMIN_USER = process.env.PORTAL_ADMIN_USER || 'admin'
export const PORTAL_ADMIN_PASSWORD = process.env.PORTAL_ADMIN_PASSWORD || 'Admin@12345'

/**
 * 门户(UnifiedLogin/login.vue) 账号密码登录：与 auth-helpers 里的管理端验证码登录不同，
 * 本环境 /#/login 是门户登录页（账号密码登录，无验证码）。登录成功后跳 /index（智数产品项目后台）。
 */
export async function loginAsPortalAdmin(page, options = {}) {
  const username = options.username || PORTAL_ADMIN_USER
  const password = options.password || PORTAL_ADMIN_PASSWORD

  await page.goto('/#/login')
  // 若默认落在“授权登录”，切到“账号密码登录”
  const pwdTab = page.locator('.login-tabs .el-tabs__item', { hasText: '账号密码登录' })
  await pwdTab.first().waitFor({ state: 'visible', timeout: 15000 }).catch(() => {})
  if (await pwdTab.first().isVisible().catch(() => false)) {
    await pwdTab.first().click().catch(() => {})
  }

  const userInput = page.locator('input[placeholder="请输入用户名"]').first()
  await userInput.waitFor({ state: 'visible', timeout: 20000 })
  await userInput.fill(username)
  await page.locator('input[placeholder="请输入用户密码"]').first().fill(password)

  // 点击登录并等待登录接口返回 200 且跳出 /login
  const respPromise = page
    .waitForResponse((r) => r.url().includes('/portal/login/login') && r.request().method() === 'POST', { timeout: 30000 })
    .catch(() => null)
  await page.locator('button', { hasText: /登\s*录/ }).first().click()
  const resp = await respPromise
  if (resp) {
    const body = await resp.json().catch(() => ({}))
    expect(body.code, `门户登录失败: ${body.msg || ''}`).toBe(200)
  }
  await page.waitForFunction(() => !location.hash.includes('/login'), null, { timeout: 30000 }).catch(() => {})
}

/** 等待后台动态路由（权限模块 addRoutes）就绪 */
export async function waitForPortalAdminReady(page, timeout = 45000) {
  await page.waitForFunction(
    () => {
      const app = document.querySelector('#app')?.__vue__
      if (!app?.$store?.getters?.roles?.length) return false
      const permission = app.$store?.state?.permission || {}
      return (permission.addRoutes?.length || 0) > 0 || (permission.originalRoutes?.length || 0) > 0
    },
    null,
    { timeout }
  )
}

/** 在浏览器侧收集可导航路由（filePath / menuId / path） */
export async function collectPortalRoutes(page) {
  return page.evaluate(() => {
    const app = document.querySelector('#app')?.__vue__
    const router = app?.$router
    const store = app?.$store
    const collected = []
    const walk = (nodes, parentPath) => {
      for (const node of nodes || []) {
        if (!node?.path) continue
        const full = node.path.startsWith('/') ? node.path : `${parentPath}/${node.path}`.replace(/\/+/g, '/')
        const filePath = node.meta?.filePath || (typeof node.component === 'string' ? node.component : null)
        if (node.meta?.menuId || filePath) {
          collected.push({ path: full, filePath, menuId: node.meta?.menuId, title: node.meta?.title })
        }
        if (node.children?.length) walk(node.children, full)
      }
    }
    if (typeof router?.getRoutes === 'function') {
      for (const route of router.getRoutes()) {
        if (!route.meta?.filePath) continue
        collected.push({ path: route.path, filePath: route.meta.filePath, menuId: route.meta?.menuId, title: route.meta?.title })
      }
    }
    if (!collected.length) {
      walk(store?.state?.permission?.originalRoutes || [], '')
      if (!collected.length) walk(store?.state?.permission?.addRoutes || [], '')
    }
    return collected
  })
}

/** 按 filePath 跳转到后台页面（hash 路由） */
export async function gotoPortalPageByFilePath(page, filePath, query = {}) {
  await waitForPortalAdminReady(page)
  const routes = await collectPortalRoutes(page)
  const matched = routes.filter((r) => r.filePath === filePath && !String(r.path).includes(':tableid'))
  const pick = matched.find((r) => !String(r.path).includes(':tableid')) || matched[0]
  if (!pick) {
    throw new Error(`未找到路由 filePath=${filePath}，当前可见路由：${JSON.stringify(routes.slice(0, 30))}`)
  }
  const qs = new URLSearchParams(query).toString()
  const hash = qs ? `${pick.path}?${qs}` : pick.path
  await page.evaluate(async (target) => {
    const router = document.querySelector('#app')?.__vue__?.$router
    await router.push(target)
  }, hash)
  await page.waitForFunction(
    (expectedPath) => {
      const cur = document.querySelector('#app')?.__vue__?.$router?.currentRoute
      return cur && cur.path === expectedPath.split('?')[0]
    },
    hash,
    { timeout: 15000 }
  ).catch(() => {})
}

import { test, expect } from '@playwright/test'
import { loginAsPortalAdmin, waitForPortalAdminReady, gotoPortalPageByFilePath } from '../fixtures/portal-auth-helpers.js'

test('smoke: admin reaches externalInfo list', async ({ page }) => {
  await loginAsPortalAdmin(page)
  await waitForPortalAdminReady(page)
  await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
  await page.waitForTimeout(2500)
  const headers = await page.locator('.el-table__header-wrapper th').allTextContents().catch(() => [])
  const hasList = await page.locator('.list-container').first().isVisible().catch(() => false)
  const rows = await page.locator('.el-table__body-wrapper tbody tr').count()
