import { test, expect } from '@playwright/test'
import {
  loginAsPortalAdmin,
  waitForPortalAdminReady,
  gotoPortalPageByFilePath,
  collectPortalRoutes
} from '../fixtures/portal-auth-helpers.js'

const BASE_TITLE = `E2E对外信息_${Date.now()}`

// 关闭新手引导 + 每页 10 条
async function prepare(page) {
  await page.addInitScript(() => {
    localStorage.setItem('driverList', 'true')
    localStorage.setItem('driverDetail', 'true')
  })
}

async function waitTable(page) {
  await page.waitForTimeout(800)
  await page.waitForFunction(() => {
    const mask = document.querySelector('.el-loading-mask')
    if (mask && getComputedStyle(mask).display !== 'none') return false
    return !!document.querySelector('.el-table')
  }, null, { timeout: 20000 }).catch(() => {})
}

async function queryList(page, { title } = {}) {
  // 标题搜索
  const titleInput = page.locator('.zs-search-form input[placeholder="请输入标题"]').first()
  if (title && await titleInput.count()) {
    await titleInput.fill(title)
  }
  const searchBtn = page.locator('.zs-search-form button', { hasText: /搜索|查询/ }).first()
  if (await searchBtn.count()) {
    await searchBtn.click()
  } else {
    await page.locator('button', { hasText: /搜索|查询/ }).first().click()
  }
  await waitTable(page)
}

async function resetSearch(page) {
  const resetBtn = page.locator('.zs-search-form button', { hasText: '重置' }).first()
  if (await resetBtn.count()) {
    await resetBtn.click()
  } else {
    await page.locator('button', { hasText: '重置' }).first().click()
  }
  await waitTable(page)
}

function rows(page) {
  return page.locator('.el-table__body-wrapper tbody tr.el-table__row, .el-table__fixed-body-wrapper tbody tr.el-table__row')
}

test.describe('对外信息配置', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page)
    await loginAsPortalAdmin(page)
    await waitForPortalAdminReady(page)
    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
  })

  test('列表展示：查询条件、操作按钮、表格列齐全', async ({ page }) => {
    // 查询条件
    await expect(page.locator('.zs-search-form input[placeholder="请输入标题"]').first()).toBeVisible()
    // 顶部操作按钮
    for (const label of ['新增', '发布', '下架', '删除', '设为置顶', '取消置顶']) {
      await expect(page.locator('.list-card button', { hasText: label }).first()).toBeVisible()
    }
    // 表头
    const headers = (await page.locator('.el-table__header-wrapper th').allTextContents()).map((t) => t.replace(/\s+/g, ''))
    for (const h of ['序号', '类型', '标题', '置顶状态', '发布用户', '发布时间', '发布状态', '操作']) {
      expect(headers).toContain(h)
    }
  })

  test('新增：创建一个对外信息并出现在列表中', async ({ page }) => {
    await page.locator('.list-card button', { hasText: '新增' }).first().click()
    // 进入 add 页
    await page.waitForFunction(() => location.hash.includes('/add'), null, { timeout: 15000 })
    await waitTable(page)
    await page.waitForTimeout(1000)

    // 类型：默认已选；标题
    const titleInput = page.locator('.el-form input[placeholder="请输入标题"]').first()
    await titleInput.waitFor({ state: 'visible', timeout: 15000 })
    await titleInput.fill(BASE_TITLE)
    // 信息来源
    const sourceInput = page.locator('.el-form input[placeholder="请输入"]').first()
    if (await sourceInput.count()) { await sourceInput.fill('E2E来源') }

    // 富文本内容：直接定位编辑器可编辑区域
    const editor = page.locator('.zs-editor .ql-editor, .ql-editor, [contenteditable="true"]').first()
    if (await editor.count()) {
      await editor.click()
      await page.keyboard.type('E2E 自动化测试文章正文内容。')
    }

    // 保存
    await page.locator('button', { hasText: /保\s*存/ }).first().click()
    // 成功提示或跳回列表
    await page.waitForFunction(
      () => !location.hash.includes('/add') || document.querySelector('.el-message--success'),
      null,
      { timeout: 20000 }
    ).catch(() => {})

    // 回列表搜索确认
    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
    await queryList(page, { title: BASE_TITLE })
    const matchRow = page.locator('.el-table__body-wrapper tbody tr', { hasText: BASE_TITLE }).first()
    await expect(matchRow).toBeVisible({ timeout: 15000 })
  })

  test('查询：按标题精确筛选', async ({ page }) => {
    const firstTitle = (await page.locator('.el-table__body-wrapper tbody tr').first().locator('td').nth(3).textContent())?.trim()
    test.skip(!firstTitle, '无数据可查询')
    await queryList(page, { title: firstTitle })
    const count = await rows(page).count()
    expect(count).toBeGreaterThanOrEqual(1)
    await resetSearch(page)
  })

  test('查看详情：展示标题与正文', async ({ page }) => {
    const viewBtn = page.locator('.el-table__fixed-right button, .operate-column-button-container button', { hasText: '查看' }).first()
    if (!(await viewBtn.count())) test.skip(true, '无查看按钮')
    await viewBtn.click()
    await page.waitForFunction(() => location.hash.includes('/system/externalInfo/') && !location.hash.includes('/add'), null, { timeout: 15000 }).catch(() => {})
    await page.waitForTimeout(1500)
    // 基本信息标题存在
    await expect(page.locator('.detail-container, .detail-from-container').first()).toBeVisible({ timeout: 15000 })
  })
})

