import { test, expect } from '@playwright/test'
import {
  loginAsPortalAdmin,
  waitForPortalAdminReady,
  gotoPortalPageByFilePath
} from '../fixtures/portal-auth-helpers.js'

const STAMP = Date.now()
const NEW_TITLE = `E2E对外信息_${STAMP}`

async function prepare(page) {
  await page.addInitScript(() => {
    localStorage.setItem('driverList', 'true')
    localStorage.setItem('driverDetail', 'true')
  })
}

async function waitTable(page) {
  await page.waitForFunction(() => {
    const mask = document.querySelector('.el-loading-mask')
    if (mask && getComputedStyle(mask).display !== 'none') return false
    return !!document.querySelector('.el-table')
  }, null, { timeout: 20000 }).catch(() => {})
  await page.waitForTimeout(600)
}

async function searchByTitle(page, title) {
  const input = page.locator('input[placeholder="请输入标题"]').first()
  await input.fill(title)
  await page.locator('.el-form button, .list-container button', { hasText: /搜\s*索|查\s*询/ }).first().click()
  await waitTable(page)
}

async function resetSearch(page) {
  await page.locator('button', { hasText: '重置' }).first().click()
  await waitTable(page)
}

function bodyRows(page) {
  return page.locator('.el-table__body-wrapper tbody tr.el-table__row')
}

/** 在指定标题行点击操作列按钮（fixed-right 不含首列复选框，按行文字定位） */
async function clickRowOperate(page, rowTitle, label) {
  // fixed-right 的行与主表行一一对应；用主表行索引映射
  const idx = await page.evaluate((t) => {
    const rows = [...document.querySelectorAll('.el-table__body-wrapper tbody tr.el-table__row')]
    return rows.findIndex((r) => r.textContent.includes(t))
  }, rowTitle)
  expect(idx, `未找到标题为 ${rowTitle} 的行`).toBeGreaterThanOrEqual(0)
  const frRows = page.locator('.el-table__fixed-right .el-table__fixed-body-wrapper tbody tr.el-table__row')
  const target = frRows.nth(idx).locator('button', { hasText: label }).first()
  await target.click()
}

async function fillAddForm(page, { title, content }) {
  await page.waitForFunction(() => location.hash.includes('/add'), null, { timeout: 15000 })
  await waitTable(page)
  await page.waitForTimeout(800)
  const titleInput = page.locator('.el-form input[placeholder="请输入标题"]').first()
  await titleInput.waitFor({ state: 'visible', timeout: 15000 })
  await titleInput.fill(title)
  const editor = page.locator('.ql-editor, .zs-editor [contenteditable="true"], [contenteditable="true"]').first()
  await editor.waitFor({ state: 'visible', timeout: 15000 })
  await editor.click()
  await page.keyboard.type(content)
}

async function saveForm(page) {
  await page.locator('button', { hasText: /保\s*存/ }).first().click()
  await page.waitForFunction(
    () => !location.hash.includes('/add') || !!document.querySelector('.el-message--success'),
    null,
    { timeout: 20000 }
  ).catch(() => {})
}

test.describe('对外信息配置', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page)
    await loginAsPortalAdmin(page)
    await waitForPortalAdminReady(page)
    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
  })

  test('01 列表展示：查询条件、操作按钮、表格列齐全', async ({ page }) => {
    await expect(page.locator('input[placeholder="请输入标题"]').first()).toBeVisible()
    // 顶部批量操作按钮
    for (const label of ['新增', '发布', '下架', '删除', '设为置顶', '取消置顶']) {
      await expect(page.locator('.list-card .el-button', { hasText: label }).first()).toBeVisible()
    }
    // 表头
    const headers = (await page.locator('.el-table__header-wrapper th').allTextContents()).map((t) => t.replace(/\s+/g, ''))
    for (const h of ['序号', '类型', '标题', '置顶状态', '发布用户', '发布时间', '发布状态', '操作']) {
      expect(headers).toContain(h)
    }
  })

  test('02 新增：创建对外信息并可在列表查到', async ({ page }) => {
    await page.locator('.list-card .el-button', { hasText: '新增' }).first().click()
    await fillAddForm(page, { title: NEW_TITLE, content: 'E2E 自动化测试文章正文内容。' })
    await saveForm(page)

    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
    await searchByTitle(page, NEW_TITLE)
    await expect(page.locator('.el-table__body-wrapper tbody tr', { hasText: NEW_TITLE }).first()).toBeVisible({ timeout: 15000 })
    await resetSearch(page)
  })

  test('03 查询：按标题筛选返回命中行', async ({ page }) => {
    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    const firstTitle = (await bodyRows(page).first().locator('td').nth(3).textContent())?.trim()
    test.skip(!firstTitle, '无数据')
    await searchByTitle(page, firstTitle)
    const matched = page.locator('.el-table__body-wrapper tbody tr', { hasText: firstTitle })
    expect(await matched.count()).toBeGreaterThanOrEqual(1)
    await resetSearch(page)
  })

  test('04 查看详情：展示基本信息与正文', async ({ page }) => {
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    const firstTitle = (await bodyRows(page).first().locator('td').nth(3).textContent())?.trim()
    await clickRowOperate(page, firstTitle, '查看')
    await page.waitForFunction(() => /\/system\/externalInfo\/\d+/.test(location.hash), null, { timeout: 15000 })
    await page.waitForTimeout(1200)
    await expect(page.locator('.detail-container, .detail-from-container').first()).toBeVisible({ timeout: 15000 })
    // 基本信息标题
    await expect(page.locator('text=基本信息').first()).toBeVisible({ timeout: 10000 })
  })

  test('05 编辑：修改未发布记录标题并保存', async ({ page }) => {
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    // 找到一条“未发布/已撤回”可编辑的记录
    const editable = await page.evaluate(() => {
      const rows = [...document.querySelectorAll('.el-table__body-wrapper tbody tr.el-table__row')]
      const idx = rows.findIndex((r) => /未发布|已撤回/.test(r.textContent))
      return idx >= 0 ? { idx, title: rows[idx].querySelectorAll('td')[3]?.textContent.trim() } : null
    })
    test.skip(!editable, '无可编辑（未发布/已撤回）记录')
    const newTitle = `${editable.title}_edited_${STAMP}`
    await clickRowOperate(page, editable.title, '编辑')
    await page.waitForFunction(() => location.hash.includes('/system/externalInfo/') && !location.hash.includes('/add'), null, { timeout: 15000 }).catch(() => {})
    await waitTable(page)
    await page.waitForTimeout(1000)
    const titleInput = page.locator('.el-form input[placeholder="请输入标题"]').first()
    await titleInput.waitFor({ state: 'visible', timeout: 15000 })
    await titleInput.fill(newTitle)
    await page.locator('button', { hasText: /保\s*存/ }).first().click()
    await page.waitForFunction(() => !location.hash.includes('/edit') && (!!document.querySelector('.el-message--success') || location.hash.endsWith('/index')), null, { timeout: 20000 }).catch(() => {})
  })

  test('06 发布：选中未发布记录发布成功', async ({ page }) => {
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    const idx = await page.evaluate(() => {
      const rows = [...document.querySelectorAll('.el-table__body-wrapper tbody tr.el-table__row')]
      return rows.findIndex((r) => /未发布|已撤回/.test(r.textContent))
    })
    test.skip(idx < 0, '无未发布/已撤回记录可发布')
    await bodyRows(page).nth(idx).locator('.el-checkbox, input[type="checkbox"]').first().click({ force: true }).catch(async () => {
      await bodyRows(page).nth(idx).locator('td').first().click({ force: true })
    })
    await page.locator('.list-card .el-button', { hasText: '发布' }).first().click()
    // 确认弹窗
    const confirm = page.locator('.el-message-box__btns button', { hasText: /确定|确 定/ })
    if (await confirm.count()) await confirm.first().click()
    await expect(page.locator('.el-message--success').first()).toBeVisible({ timeout: 15000 })
  })

  test('07 删除：选中未发布记录删除成功', async ({ page }) => {
    // 先新建一条专用于删除，避免影响其它数据
    await page.locator('.list-card .el-button', { hasText: '新增' }).first().click()
    const delTitle = `E2E待删除_${STAMP}`
    await fillAddForm(page, { title: delTitle, content: '删除用例内容。' })
    await saveForm(page)
    await gotoPortalPageByFilePath(page, 'portal/externalInfo/index')
    await waitTable(page)
    await searchByTitle(page, delTitle)
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    await bodyRows(page).first().locator('td').first().click({ force: true })
    await page.locator('.list-card .el-button', { hasText: '删除' }).first().click()
    const confirm = page.locator('.el-message-box__btns button', { hasText: /确定|确 定/ })
    if (await confirm.count()) await confirm.first().click()
    await expect(page.locator('.el-message--success').first()).toBeVisible({ timeout: 15000 })
    await waitTable(page)
    // 删除后查不到
    await searchByTitle(page, delTitle)
    await page.waitForTimeout(800)
    const left = await page.locator('.el-table__body-wrapper tbody tr', { hasText: delTitle }).count()
    expect(left).toBe(0)
  })

  test('08 设为置顶/取消置顶：状态切换成功', async ({ page }) => {
    await expect(bodyRows(page).first()).toBeVisible({ timeout: 15000 })
    // 选第一行设为置顶
    await bodyRows(page).first().locator('td').first().click({ force: true })
    await page.locator('.list-card .el-button', { hasText: '设为置顶' }).first().click()
    let confirm = page.locator('.el-message-box__btns button', { hasText: /确定|确 定/ })
    if (await confirm.count()) await confirm.first().click()
    await expect(page.locator('.el-message--success').first()).toBeVisible({ timeout: 15000 })
    await waitTable(page)
    // 再取消置顶
    await bodyRows(page).first().locator('td').first().click({ force: true })
    await page.locator('.list-card .el-button', { hasText: '取消置顶' }).first().click()
    confirm = page.locator('.el-message-box__btns button', { hasText: /确定|确 定/ })
    if (await confirm.count()) await confirm.first().click()
    await expect(page.locator('.el-message--success').first()).toBeVisible({ timeout: 15000 })
  })
})
